"""Generate text with the bit-exact golden model: prompt is fed byte by byte, then sampled."""
import argparse

from src.model.data import EOS

from ..net.model import HwModel
from .sampler import HostSampler
from ..data.weights import load_params


def generate(cfg, P, prompt, n_new, sampler):
    """-> generated bytes (stops at EOS)."""
    model = HwModel(cfg, P)
    tokens = list(prompt.encode('ascii'))
    for t in tokens[:-1]:
        model.step([t])
    out, tok = [], tokens[-1]
    for _ in range(n_new):
        tok = sampler(model.step([tok])[0])
        if tok == EOS:
            break
        out.append(tok)
    return bytes(out)


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('params', help='.npz from src.golden.data.weights')
    ap.add_argument('--prompt', default='Once upon a time')
    ap.add_argument('--n', type=int, default=300)
    ap.add_argument('--temperature', type=float, default=0.8)
    ap.add_argument('--seed', type=int, default=0)
    a = ap.parse_args()
    cfg, P = load_params(a.params)
    text = generate(cfg, P, a.prompt, a.n, HostSampler(a.temperature, a.seed))
    print(a.prompt + text.decode('ascii'))


if __name__ == '__main__':
    main()
